def task_data(task):
    return {"id": task.id, "title": task.title, "description": task.description, "status": task.status, "priority": task.priority, "due_date": task.due_date.isoformat() if task.due_date else None, "created_at": task.created_at.isoformat(), "updated_at": task.updated_at.isoformat()}